def solve(inputs: dict) -> float:
    X = inputs['initial']
    steps = inputs['steps']
    shifts = inputs['shifts']  # list of (direction, amount) tuples
    mask = (1 << 32) - 1  # 32-bit mask

    for _ in range(steps):
        for direction, amount in shifts:
            if direction == 'left':
                X = (X ^ ((X << amount) & mask)) & mask
            else:  # right
                X = (X ^ (X >> amount)) & mask

    return float(X)

